// A temporary view of the original photos. It never changes attachments or covers.
export function fitPhoto(width,height,boxWidth,boxHeight){const scale=Math.min(boxWidth/width,boxHeight/height);return width>0&&height>0&&boxWidth>0&&boxHeight>0?{width:width*scale,height:height*scale}:{width:0,height:0};}
export function constrainPhoto(view,fit,box){const scale=Math.max(1,Math.min(5,Number(view.scale)||1)),limitX=Math.max(0,(fit.width*scale-box.width)/2),limitY=Math.max(0,(fit.height*scale-box.height)/2);return {scale,x:Math.max(-limitX,Math.min(limitX,view.x||0)),y:Math.max(-limitY,Math.min(limitY,view.y||0))};}
export function createPhotoLightbox({document,window}){
 const $=id=>document.getElementById(id),viewport=$('enlarged-viewport'),image=$('enlarged-image'),pointers=new Map();
 let photos=[],index=0,title='',fit={width:0,height:0},box={width:0,height:0},view={scale:1,x:0,y:0},gesture=null,lastTap=null,active=false,ready=false,failed=false;
 function render(){view=constrainPhoto(view,fit,box);image.style.width=fit.width+'px';image.style.height=fit.height+'px';image.style.transform=`translate(${view.x}px,${view.y}px) scale(${view.scale})`;viewport.classList.toggle('zoomed',view.scale>1);$('photo-zoom-in').disabled=!ready||view.scale>=5;$('photo-zoom-out').disabled=!ready||view.scale<=1;$('photo-fit').disabled=!ready||view.scale===1;$('enlarged-zoom').textContent=ready?Math.round(view.scale*100)+'%':'';}
 function measure(){if(!active||!ready)return;const r=viewport.getBoundingClientRect();box={width:r.width,height:r.height};fit=fitPhoto(image.naturalWidth,image.naturalHeight,r.width,r.height);render();}
 function clearPointers(){for(const id of pointers.keys())try{if(viewport.hasPointerCapture?.(id))viewport.releasePointerCapture(id);}catch{}pointers.clear();gesture=null;}
 function show(){clearPointers();lastTap=null;view={scale:1,x:0,y:0};ready=false;failed=false;fit={width:0,height:0};$('enlarged-caption').textContent=title;$('enlarged-count').textContent=`${index+1} / ${photos.length}`;$('enlarged-status').textContent='Loading photo…';for(const id of ['enlarged-previous','enlarged-next'])$(id).hidden=photos.length<2;image.alt=`Photo ${index+1} of ${photos.length}${title?' of '+title:''}`;image.hidden=true;render();image.src=photos[index];}
 function reset(){active=false;clearPointers();photos=[];title='';lastTap=null;ready=false;failed=false;image.removeAttribute('src');image.alt='';image.hidden=true;image.style.transform='';$('enlarged-caption').textContent='';$('enlarged-count').textContent='';$('enlarged-status').textContent='';$('enlarged-zoom').textContent='';}
 function move(step){if(!active||photos.length<2)return;index=(index+step+photos.length)%photos.length;show();}
 function zoom(scale,cx=box.width/2,cy=box.height/2){if(!ready)return;const next=Math.max(1,Math.min(5,scale)),ratio=next/view.scale;view={scale:next,x:(cx-box.width/2)-(cx-box.width/2-view.x)*ratio,y:(cy-box.height/2)-(cy-box.height/2-view.y)*ratio};render();}
 image.onload=()=>{if(!active||failed)return;ready=!!image.naturalWidth;image.hidden=!ready;$('enlarged-status').textContent=ready?'':'This photo could not be displayed.';measure();};
 image.onerror=()=>{if(!active)return;failed=true;ready=false;image.hidden=true;$('enlarged-status').textContent='This photo could not be displayed. Close this view and try again.';render();};
 const distance=()=>{const [a,b]=[...pointers.values()];return Math.hypot(a.x-b.x,a.y-b.y);};
 function begin(){const [a,b]=[...pointers.values()];if(!a){gesture=null;return;}gesture={start:{...view},x:a.x,y:a.y,moved:false,multi:!!b};if(b){gesture.distance=distance();gesture.mid={x:(a.x+b.x)/2,y:(a.y+b.y)/2};}}
 viewport.addEventListener('pointerdown',e=>{if(!active||!ready||e.button>0||pointers.size>=2)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});viewport.setPointerCapture?.(e.pointerId);begin();});
 viewport.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId)||!gesture)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});const [a,b]=[...pointers.values()];if(b){const scale=Math.max(1,Math.min(5,gesture.start.scale*distance()/Math.max(1,gesture.distance))),ratio=scale/gesture.start.scale,r=viewport.getBoundingClientRect(),x=gesture.mid.x-r.left-box.width/2,y=gesture.mid.y-r.top-box.height/2;view={scale,x:(a.x+b.x)/2-r.left-box.width/2-(x-gesture.start.x)*ratio,y:(a.y+b.y)/2-r.top-box.height/2-(y-gesture.start.y)*ratio};gesture.moved=true;lastTap=null;}else{const dx=a.x-gesture.x,dy=a.y-gesture.y;if(Math.abs(dx)>8||Math.abs(dy)>8)gesture.moved=true;if(view.scale>1)view={...view,x:gesture.start.x+dx,y:gesture.start.y+dy};}render();if(e.cancelable)e.preventDefault();});
 function end(e,cancelled=false){if(!pointers.has(e.pointerId))return;const g=gesture,wasMultiple=pointers.size>1;pointers.delete(e.pointerId);if(viewport.hasPointerCapture?.(e.pointerId))viewport.releasePointerCapture(e.pointerId);if(!cancelled&&!wasMultiple&&g&&!g.multi){const dx=e.clientX-g.x,dy=e.clientY-g.y;if(g.start.scale===1&&Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.3){move(dx<0?1:-1);return;}if(!g.moved&&Math.abs(dx)<8&&Math.abs(dy)<8){const now=Date.now();if(lastTap&&now-lastTap.time<320&&Math.hypot(e.clientX-lastTap.x,e.clientY-lastTap.y)<30){const r=viewport.getBoundingClientRect();zoom(view.scale>1?1:2.5,e.clientX-r.left,e.clientY-r.top);lastTap=null;}else lastTap={time:now,x:e.clientX,y:e.clientY};}}begin();if(wasMultiple&&gesture)gesture.multi=true;}
 viewport.addEventListener('pointerup',e=>end(e));viewport.addEventListener('pointercancel',e=>{lastTap=null;end(e,true);});viewport.addEventListener('lostpointercapture',e=>{if(pointers.delete(e.pointerId)){lastTap=null;begin();if(gesture)gesture.multi=true;}});
 viewport.addEventListener('wheel',e=>{if(!ready)return;e.preventDefault();const r=viewport.getBoundingClientRect();zoom(view.scale*(e.deltaY<0?1.2:1/1.2),e.clientX-r.left,e.clientY-r.top);},{passive:false});
 $('photo-lightbox').addEventListener('keydown',e=>{if(!active||e.altKey||e.ctrlKey||e.metaKey)return;let handled=true;if(view.scale>1&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){view={...view,x:view.x+(e.key==='ArrowLeft'?60:e.key==='ArrowRight'?-60:0),y:view.y+(e.key==='ArrowUp'?60:e.key==='ArrowDown'?-60:0)};render();}else if(e.key==='ArrowLeft')move(-1);else if(e.key==='ArrowRight')move(1);else if(e.key==='+'||e.key==='=')zoom(view.scale*1.5);else if(e.key==='-')zoom(view.scale/1.5);else if(e.key==='0')zoom(1);else handled=false;if(handled){e.preventDefault();e.stopPropagation();}});
 $('photo-zoom-in').onclick=()=>zoom(view.scale*1.5);$('photo-zoom-out').onclick=()=>zoom(view.scale/1.5);$('photo-fit').onclick=()=>zoom(1);$('enlarged-previous').onclick=()=>move(-1);$('enlarged-next').onclick=()=>move(1);window.addEventListener('resize',measure);
 return {open({photos:items,index:chosen=0,title:label=''}){reset();photos=items.slice();if(!photos.length)return false;active=true;title=label;index=Math.max(0,Math.min(photos.length-1,chosen));show();return true;},reset};
}
